async function refresh(){if(!A.user)return;const [m,da]=await Promise.all([sb.from("carrier_members").select("carrier_id,member_role").eq("user_id",A.user.id).eq("status","active").maybeSingle(),sb.from("driver_applications").select("*").eq("user_id",A.user.id).maybeSingle()]);if(m.error)throw m.error;if(da.error)throw da.error;A.driverApplication=da.data||null;A.driverDocuments=[];if(A.driverApplication){const docs=await sb.from("driver_application_documents").select("*").eq("user_id",A.user.id).order("created_at",{ascending:false});if(docs.error)throw docs.error;A.driverDocuments=docs.data||[]}if(!m.data){A.carrier=null;A.vehicles=[];A.drivers=[];A.documents=[];A.assignments=[];return}const id=m.data.carrier_id;const [c,v,d,docs,assignments]=await Promise.all([sb.from("carriers").select("*").eq("id",id).single(),sb.from("vehicles").select("*").eq("carrier_id",id).order("created_at",{ascending:false}),sb.from("drivers").select("*").eq("carrier_id",id).order("created_at",{ascending:false}),sb.from("documents").select("*").eq("carrier_id",id).order("created_at",{ascending:false}),sb.from("driver_vehicle_assignments").select("id,driver_id,vehicle_id,valid_from,valid_to,notes,drivers(first_name,last_name),vehicles(registration_plate,brand,model)").eq("carrier_id",id).order("created_at",{ascending:false})]);for(const x of [c,v,d,docs,assignments])if(x.error)throw x.error;A.carrier=c.data;A.vehicles=v.data||[];A.drivers=d.data||[];A.documents=docs.data||[];A.assignments=assignments.data||[]}
